list_categories.code:
const response = await client.categories.listCategories({limit: 10, offset: 10, sort: 'name', dir: 'asc'});
for (const category of response.map.categories) {
    console.log(category.id, category.general.name, category.general.url);
}
console.log(response.map.pagination.total);

create_category.code:
const response = await client.categories.createCategory({
    category: {
        general: {
            name: 'Seasonal Produce',
            title: 'Seasonal Produce',
            heading: 'Fresh this season',
            summary: 'Fruit and vegetables picked this week',
            parent_category: {id: 4310},
        },
        description: {content: '<p>What is in season right now.</p>'},
        availability_visibility: {visible: true, custom_sorting: true, default_sorting: 'alpha_asc'},
        tax_shipping: {tax_message: 'Prices include GST'},
        assign_products: {products: [101, 102]},
    },
});
const category = response.map.category;
console.log(category.id, category.general.sku, category.general.url);

get_category.code:
const response = await client.categories.getCategory(4321);
const category = response.map.category;
console.log(category.general.name, category.general.parent_category.name, category.in_trash);

update_category.code:
const response = await client.categories.updateCategory(4321, {
    category: {general: {name: 'Seasonal Produce', heading: 'New heading'}},
});
const category = response.map.category;
console.log(category.general.heading, category.general.url, category.assign_products.products.length);

patch_category.code:
const response = await client.categories.patchCategory(4321, {
    category: {general: {summary: 'Updated summary'}, availability_visibility: {visible: false}},
});
const category = response.map.category;
console.log(category.general.summary, category.availability_visibility.visible);

get_category_section.code:
const response = await client.categories.getCategorySection(4321, 'tax_shipping');
const taxShipping = response.map.category.tax_shipping;
console.log(taxShipping.tax_profile.name, taxShipping.enable_shipping, taxShipping.shipping_profile.name);

patch_category_section.code:
const response = await client.categories.patchCategorySection(4321, 'assign_products', {
    category: {assign_products: {products: [101, 102, 103]}},
});
for (const product of response.map.category.assign_products.products) {
    console.log(product.id, product.name, product.sku);
}
